#[test]
fn rejected_queue_insert_rolls_back_message_metadata() {
    let (_dir, store) = fixture();
    let before: i64 = store.with_conn(|conn| {
        Ok(conn.query_row("SELECT COUNT(*) FROM messages", [], |row| row.get(0))?)
    }).unwrap();
    store.with_conn(|conn| {
        conn.execute_batch("CREATE TRIGGER reject_queue BEFORE INSERT ON outbox_queue
            BEGIN SELECT RAISE(ABORT, 'simulated disk failure'); END;")?;
        Ok(())
    }).unwrap();
    assert!(store.queue_outbox_message(draft()).is_err());
    let after: i64 = store.with_conn(|conn| {
        Ok(conn.query_row("SELECT COUNT(*) FROM messages", [], |row| row.get(0))?)
    }).unwrap();
    assert_eq!(before, after);
    assert!(store.list_outbox().unwrap().is_empty());
}

